\label{prop: geometricconvergence}
The pants $P_x$ geometrically converges to 
 $P_0$, as $x$ goes to $0$. In particular, there is a $C_{x}$-biLipschitz mapping 
 from the truncated $P_x^1$ to the truncated $P_{0}^1$ which 
 \begin{enumerate}
 \item when restricted to the boundary curves is an isometry 
 \item respects the endpoints of a simple orthogeodesic going from one boundary curve to another. 
 \end{enumerate}
 The constant $C_{x}$ is monotone and goes to 1, as $x$ goes to $0$.

\label{prop:bishop}
Suppose $X$ and $Y$ are hyperbolic surfaces and there is a pants decomposition for which both $X$ and $Y$ have upper bounded pants curves and upper bounded ratios of pants lengths, then 
there is a quasiconformal homeomorphism between $X$ and $Y$ with a constant that just depends on these two bounds.

(Type III) \label{lem: typeIII}
 Suppose $\gamma$ is a closed curve with self-intersection number $n$ with geodesic arcs $\mathcal{A}$ passing through 
 $\mathcal{C}_{\alpha}(x)$, where $x \leq \frac{1}{5n}$. 
 Let $\mathcal{A}^{\prime}$ be any set of geodesic arcs passing through $\mathcal{C}_{\alpha}(\frac{1}{n})$ with the same number of arcs and total geometric winding number as $\mathcal{A}$. Then 

\begin{equation} \label{eq: sumofstrands}
\sum_{s^{\prime} \in \mathcal{A}^{\prime}} \ell_{s^{\prime}} \left(\frac{1}{n}\right)
\leq \sum_{s \in \mathcal{A}} \ell_{s}\left(x \right).
\end{equation}

For the lower bound, take any topologically embedded pair of pants $P \subset \Sigma$, and consider the set of closed curves on $P$. Note that the inf length of any curve in $P$ is realized on the ideal pair of pants and hence the set of inf lengths of these curves by Huber's theorem grow like $\frac{e^{L}}{2L}$. Since the (orientation preserving)  mapping class group of $P$ is of order $6$, we can conclude that the growth rate of these curves is at least 
$\frac{1}{6} (\frac{e^{L}}{2L})$. 
Now, if $P^{\prime}$ is a pair of pants not in the $\mathrm{Mod}_{g}$-orbit of $P$, then by 
 Lemma \ref{lem:mcgorbits}, item (2), the closed curves on $P^{\prime}$ are distinct from the closed curves on $P$. Letting $A_g$ be the number of $\mathrm{Mod}_{g}$-orbits of punctured tori (there is only one)
and pants in $\Sigma$, we may conclude 
 that 

\begin{equation*}
 \# \bigl\{[\gamma] \mid m_{[\gamma]} \leq L \bigr\}\geq A_g \frac{e^{L}}{2L} 
\end{equation*}

for $L \geq L_{0}$. This establishes the lower bound. 

For the proof of the upper bound, recall that $Y_{\gamma}$ denotes the thickened surface associated to the optimal metric, $X_{\gamma}$, with 
${\rm sys} (Y_{\gamma}) \geq \frac{1}{5 i(\gamma, \gamma)}$. We use the fact that the number of self-intersections of a closed geodesic of length at most $L$ is universally bounded by $2e^{2L}$ (see \cite{basmajian2013universal}). Setting $n= 2e^{2L}$ we have 
\begin{equation} \label{eq: equality}
\{[\gamma]\mid \ell_{\gamma}(Y_{\gamma}) \leq L \} = \bigcup_{i(\gamma, \gamma)=1}^{n} \{[\gamma]\mid \ell_{\gamma}(Y_{\gamma})\leq L\} 
\end{equation}
\begin{equation}\label{eq: containment}
\subset \bigcup_{i(\gamma , \gamma)=1}^{n} \bigcup_{Z \in \mathbf{M}_g^{n}} \{[\gamma]\mid \frac{1}{Q_{g}} \ell_{\gamma}(Z) \leq L \} 
\end{equation}
 Line (\ref{eq: containment}) follows from Lemma \ref{lem: model metric properties} item (\ref{item: qc constant}), which guarantees that for any $Y_{\gamma}$ there is a model metric in $\mathbf{M}_g^{n}$ and a $Q_{g}$- quasiconformal mapping between them. 
Now, using the above containment we have 



\begin{equation}\label{eq: equality2}
\#\{[\gamma]\mid \ell_{\gamma}(Y_{\gamma}) \leq L \}
= \sum_{i(\gamma, \gamma)=1}^{n} \#\{[\gamma]\mid \ell_{\gamma}(Y_{\gamma})\leq L\}
\end{equation}

\begin{align}
\label{eq: buser lemma}
\leq{}& \sum_{i(\gamma, \gamma)=1}^{n} \sum_{Z \in \mathbf{M}_g^{n}}
\#\{[\gamma]\mid \ell_{\gamma}(Z_{\gamma})\leq Q_g L\}
\leq \sum_{i(\gamma, \gamma)=1}^{n} \sum_{Z \in \mathbf{M}_g^{n}} a e^{Q_g L}
\\
\label{eq:numbermodelmetrics}
\leq{}& a e^{Q_g L} \sum_{i(\gamma, \gamma)=1}^{n} \sum_{Z \in \mathbf{M}_g^{n}} 1
= a ne^{Q_g L} \, \#\{Z \in \mathbf{M}_g^{n}\}
= a ne^{Q_g L} t_{g} (n+1)^{3g-3}
\\
\label{eq: final inequality}
={}& 2a t_{g} e^{(2+Q_g)L} 2^{3g-3}e^{(6g-6)L}
\left(1+\frac{1}{2e^{2L}}\right)^{3g-3}
\leq 2^{6g-5} a t_{g} e^{(6g-4+Q_g)L}
\end{align}

where the right-hand side of inequality (\ref{eq: buser lemma}) with constant 
$a=(g-1)e^{6}$ follows from Lemma 6.6.4 of Buser \cite{BuserBook}, in line (\ref{eq:numbermodelmetrics}) we used Lemma \ref{lem: model metric properties} item (\ref{item: modelmetricnumber}), and in line 
(\ref{eq: final inequality}) we used $n=2e^{2L}$, and in that same line the equality follows from using the fact that $1+\frac{1}{2e^{2L}} \leq 2$.

Finally, recalling Proposition \ref{prop: thickened metric} and plugging into line (\ref{eq: final inequality}) with $a=(g-1)e^{6}$ we have

\begin{equation}
\#\{[\gamma] \mid \ell_{\gamma}(X_{\gamma}) \leq L\} \leq \#\{[\gamma] \mid \ell_{\gamma}(Y_{\gamma}) \leq cL\} 
\end{equation}
\begin{equation*}
\leq (g-1)e^6 t_g 2^{6g-5} e^{(6g-4+Q_g)cL}
\end{equation*}

Finally, setting $B=(g-1)e^6 t_g 2^{6g-5}$ and $C=(6g-4+Q_g)c$, and noting that $B$
and $C$ only depend on topology yields the desired result.

\label{lem:mcgorbits}
 Suppose $\Sigma$ is a closed surface of genus $g \geq 2$. Then

\begin{enumerate}
 \item there is only one type of embedded punctured torus in $\Sigma.$
 Moreover, there is only one type of figure $8$ which is contained in the punctured torus. 
 \item Two essential closed curves in embedded pairs of pants, $\gamma \subset P$ and $\gamma^{\prime} \subset P^{\prime}$, are in the same orbit if and only if $P$ and $P^{\prime}$ are in the same orbit. 
 \end{enumerate}

\label{enum: counting}
Consider the closed surface $\Sigma$ of genus $g \geq 2$. Then
\begin{enumerate} 
 \item the number of $\mathrm{Mod}_{g}$-orbits of embedded pairs of pants in $\Sigma$ is 
\begin{equation}
 (g-1)+ \floor*{\frac{g^2+3}{12}}
\end{equation}

 \item 
 the number of $\mathrm{Mod}_{g}$-orbits of figure $8$ curves in $\Sigma$ is 
 \begin{equation}
 2g-2+\floor*{\frac{(g-1)^2}{4}}
 \end{equation}

\end{enumerate}

Either count involves considering an embedded pair of pants $P$ in $\Sigma$. Such a pair of pants has either 1, 2, or 3 complementary components $\Sigma\backslash P$. We count the number of such complementary components in each case. 

\noindent{\bf 1 complementary component:} 
In this case, an embedded pair of pants has complement a genus $g-2$ surface with 3 boundary components. See Figure \ref{fig:1 component}. Hence, there is 1 embedded pair of pants. Next to count figure 8's note that either the figure 8 is in a punctured torus or an embedded pair of pants. In the case of a punctured torus by Lemma \ref{lem:mcgorbits} item (1) there is a single figure 8. In the case of an embedded pair
of pants $P$, since any of the boundary curves of $P$ are equivalent, there is only 1 figure $8$ curve in an embedded pair of pants with one complementary component. We may conclude there are exactly 2 figure 8's in this case. 



\begin{figure}[h]
 \centering
 \begin{overpic}[trim={2cm 7cm 8cm 6cm}, clip, width=0.65\linewidth]{1component.pdf}
 \put(25,41){$a$}
 \end{overpic}
 \caption{Embedded pair of pants with 1 complementary component and distinguished boundary $a$. }
 \label{fig:1 component}
\end{figure}

\noindent{\bf 2 complementary components:} In this case, one of the components has a single boundary curve, and the other complementary component has 2 boundary curves. See Figure \ref{fig:2 component both}. Denote the genus of the complementary component with one boundary curve by $a$, and denote the genus of the other complementary component as $g_1$. Now $a+g_1=g-1$, where $a \geq 1$ and $g_1 \geq 1.$ There are clearly $(g-2)$ possible configurations, and hence the number of embedded pairs of pants is 
$g-2$. 

To count the figure $8's$ there are two possibilities for the distinguished boundary component. Either it bounds the component with genus $a$ which has one boundary component or it bounds the component with genus $g_1$ with two boundary components. In the first case, there are 
$(g-2)$ such configurations. In the second case, there are also $(g-2)$ such possibilities. Hence, the total number of figure $8's$ is $2(g-2)$.



\begin{figure}[h]
 \centering
 \begin{subfigure}[b]{0.45\linewidth}
 \centering
 \begin{overpic}[trim={2cm 7cm 8cm 6cm}, clip, width=\linewidth]{2component.pdf}
 \put(25,41){$a$}
 \end{overpic}
 \caption{}
 \label{fig:2 component}
 \end{subfigure}
 \hfill
 \begin{subfigure}[b]{0.45\linewidth}
 \centering
 \begin{overpic}[trim={2cm 7cm 8cm 6cm}, clip, width=\linewidth]{2component2.pdf}
 \put(25,41){$a$}
 \end{overpic}
 \caption{}
 \label{fig:2component2}
 \end{subfigure}
 \caption{Embedded pair of pants with 2 complementary components and distinguished boundary $a$.}
 \label{fig:2 component both}
\end{figure}


\noindent{\bf 3 complementary components:} Here we assume $g \geq 3$ since 3 complementary components is impossible if genus $g=2$. Each of these complementary components has positive genus and one boundary component.
See Figure \ref{fig:3 component}. Denoting these genera by $a,g_1$, and $g_2$ it is not difficult to see that the total number of embedded pants is equal to 


$$
\# \{(a,g_1,g_2) | a+g_1+g_2=g, 1 \leq a \leq g_1 \leq g_2 \}
$$
but this is precisely the number of positive partitions of $g$ with exactly 3 parts which is
$$
\floor*{\frac{g^2+3}{12}}.
$$

To count the number of figure $8$ curves in this case, let $a$ be the genus with the distinguished boundary component corresponding to the figure $8$ on the pair of pants, and let 
$g_1$ and $g_2$ be the genera of the other two components. 
We know $a+g_1+g_2=g$, where $1 \leq a \leq g-2$.
Now for each $a$, note that $g_1$ and $g_2$ are interchangeable since they yield the same surface $\Sigma$ . Hence for each $a$ there are 
$$
\floor*{\frac{g-a}{2}}.
$$
Since $a$ runs between $1$ and $g-2$, we have that the total number of figure $8's$ in this case is 
\begin{equation}
 \sum_{a=1}^{g-2} \floor*{\frac{g-a}{2}}=\floor*{\frac{(g-1)^2}{4}}
\end{equation}





At this point, the proof, in any of the cases reduces to an elementary combinatorial exercise. 
We leave the count to the reader with Table \ref{table:2} providing the count for the various possible complementary components.
